public:
    MatrixWidget(QWidget *parent = nullptr) : QWidget(parent) { }

protected:
    void paintEvent(QPaintEvent *event) override
    {
        QPainter painter(this);
        painter.setRenderHint(QPainter::Antialiasing);

        // Draw your matrix here...
    }

private:
    QMatrixTransformer transformer;
    int zoomLevel = 100;

public slots:
    void zoomIn() { zoomLevel *= 1.1; }
    void zoomOut() { zoomLevel /= 1.1; }

private slots:
    void onMouseWheel(QWheelEvent *event)
    {
        if (event->delta() > 0) {
            zoomIn();
        } else {
            zoomOut();
        }
        update();
    }
};

int main(int argc, char *argv[])
{
    QApplication app(argc, argv);

    MatrixWidget widget;
    widget.show();

    return app.exec();
}
```

