To create a React hook for converting temperatures between different units, follow these steps:

1. Create a new file named `useTemperatureConverter.js` in your project directory.
2. Inside the file, define the custom hook using the `useState` and `useEffect` hooks from React:
```javascript
import { useState, useEffect } from 'react';

const useTemperatureConverter = () => {
  const [temperature, setTemperature] = useState(0);
  const [unit, setUnit] = useState('celsius');

  useEffect(() => {
    // Convert temperature to Fahrenheit when unit is changed to 'fahrenheit'
    if (unit === 'fahrenheit') {
      setTemperature((temperature * 9 / 5) + 32);
    }
  }, [unit]);

  useEffect(() => {
    // Convert temperature to Celsius when unit is changed to 'celsius'
    if (unit === 'celsius') {
      setTemperature((temperature - 32) * 5 / 9);
    }
  }, [unit]);

  return { temperature, unit, setTemperature, setUnit };
};

export default useTemperatureConverter;
```
