```python
def num_to_words(num):
    if num == 0:
        return "zero"
    elif num < 0:
        return "minus " + num_to_words(-num)
    else:
        words = []
        power = 0
        while num >= 1000:
            words.append(str(num % 1000))
            num //= 1000
            power += 3
        if num >= 100:
            words.append(str(num % 100))
            num //= 100
            power += 2
        if num >= 10:
            words.append(str(num % 10))
            num //= 10
            power += 1
        words.reverse()
        result = ""
        for i, word in enumerate(words):
            if i == 0 and word != "0":
                result += word
            elif i == 1 and word != "0":
                result += "-" + word
            elif i > 1:
                result += " " + word
        return result
