To make your planets less clustered, you can introduce a simple space filling algorithm like the Von Neumann Algorithm or the Sphere Packing Algorithm. These algorithms will help distribute the planets uniformly within the given space. Here's an example using the Von Neumann Algorithm:

```javascript
function generateRandomPlanets(numPlanets, minDistance, algorithm) {
  const planets = [];
  let attempts = 0;

  while (planets.length < numPlanets && attempts < 100) {
    attempts++;

    const planet = {
      position: [
        randomPosition(-30, 30),
        randomPosition(-30, 30),
        randomPosition(-30, 30),
      ],
      size: randomSize(1, 5) * scale,
      color: randomColor(),
      ringSize: 0.2 * scale,
      ringColor: randomColor(),
      ringNoise: 0.3 * scale,
    };

    // Use the Von Neumann Algorithm to check if the planet is too close to any existing planet
    const tooClose = planets.some((p) =>
      p.position.some((coord, index) => {
        return Math.abs(coord - planet.position[index]) < minDistance || algorithm.isNeighbor(p, planet);
      })
    );

    if (!tooClose) {
      planets.push(planet);
    }
  }

  return planets;
}

function VonNeumannAlgorithm(a, b) {
  const dx = Math.abs(b.x - a.x);
  const dy = Math.abs(b.y - a.y);
  const dz = Math.abs(b.z - a.z);

  return dx <= dy && dx <= dz ? dx : dy <= dz ? dy : dz;
}

const generatePlanetsWithVonNeumann = (numPlanets, minDistance) => {
  const planets = generateRandomPlanets(numPlanets, minDistance, (a, b) => VonNeumannAlgorithm(a, b));
  return planets;
};
```

